const INITIAL_BUDGET = YEARS.flatMap((y) => AREAS_DEFAULT.map((a) => {
  let pres = 0;
  if (a === "Quirófano") pres = y === 2025 ? 150000 : 200000;
  else if (a === "UCI") pres = y === 2025 ? 120000 : 100000;
  else if (a === "Imagenología") pres = y === 2025 ? 80000 : 90000;
  else if (a === "Emergencias") pres = y === 2025 ? 50000 : 60000;
  else if (a === "Laboratorio Clínico") pres = y === 2025 ? 40000 : 45000;
  else pres = 30000;
  return { area: a, anio: y, presupuesto: pres };
}));

